import Model from 'flarum/common/Model';

/**
 * A member's own advert.
 *
 * Deliberately smaller than the admin-side Creative: there is no weight, no
 * campaign, no slot, and no advertiser on it, because none of those are the
 * member's to see or set.
 */
export default class Submission extends Model {
  name = (() => Model.attribute('name'))();
  type = (() => Model.attribute('type'))();
  payload = (() => Model.attribute('payload'))();
  destinationUrl = (() => Model.attribute('destinationUrl'))();

  /** Read-only: a member says what their advert is, the forum says whether it runs. */
  status = (() => Model.attribute('status'))();
  reviewReason = (() => Model.attribute('reviewReason'))();
  reviewedAt = (() => Model.attribute('reviewedAt', Model.transformDate))();
  createdAt = (() => Model.attribute('createdAt', Model.transformDate))();
  updatedAt = (() => Model.attribute('updatedAt', Model.transformDate))();
}
flarum.reg.add('datlechin-placements', 'forum/models/Submission', Submission);