import app from 'flarum/forum/app';
import UserPage from 'flarum/forum/components/UserPage';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Placeholder from 'flarum/common/components/Placeholder';
import humanTime from 'flarum/common/helpers/humanTime';
import StatusPill, { creativeTone } from '../../common/components/StatusPill';
import { SUBMISSION_RESOURCE, canSubmit, trans } from '../submissions';
import SubmissionModal from './SubmissionModal';

/**
 * A member's own adverts, and what became of them.
 *
 * On the profile page because that is where Flarum already puts everything
 * belonging to one person, and it comes with the routing and the layout. The
 * tab is only ever drawn on your own profile: everything here is between one
 * member and the staff.
 */
export default class SubmissionsUserPage extends UserPage {
  submissions = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.loadUser(m.route.param('username'));
  }
  show(user) {
    super.show(user);
    this.load();
  }
  load() {
    // Never asks for a username. The endpoint answers with the actor's own
    // submissions whoever is asking, so there is nothing here to point at
    // somebody else.
    app.store.find(SUBMISSION_RESOURCE).then(submissions => {
      this.submissions = submissions;
      m.redraw();
    }).catch(() => {
      this.submissions = [];
      m.redraw();
    });
  }
  content() {
    // The route is reachable by typing it. Somebody else's profile, or a
    // viewer who may not submit, gets the same nothing the tab would have
    // shown them.
    if (!canSubmit() || this.user?.id() !== app.session.user?.id()) {
      return m(Placeholder, {
        text: trans('unavailable')
      });
    }
    return m("div", {
      className: "SubmissionsUserPage"
    }, m("div", {
      className: "SubmissionsUserPage-header"
    }, m("p", {
      className: "helpText"
    }, trans('help')), m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-plus",
      onclick: () => app.modal.show(SubmissionModal, {
        onsaved: () => this.load()
      })
    }, trans('create'))), this.submissions === null ? m(LoadingIndicator, null) : this.list());
  }
  list() {
    if (!this.submissions?.length) {
      return m(Placeholder, {
        text: trans('none')
      });
    }

    // Newest first: unlike the staff queue, which is worked from the front,
    // this is somebody looking for the thing they just sent.
    const ordered = [...this.submissions].sort((a, b) => (b.createdAt()?.getTime() ?? 0) - (a.createdAt()?.getTime() ?? 0));
    return m("ul", {
      className: "SubmissionList"
    }, ordered.map(submission => this.row(submission)));
  }
  row(submission) {
    const status = submission.status();
    return m("li", {
      className: "SubmissionList-item",
      key: String(submission.id())
    }, m("div", {
      className: "SubmissionList-summary"
    }, m("span", {
      className: "SubmissionList-name"
    }, submission.name()), m(StatusPill, {
      tone: creativeTone(status)
    }, trans(`statuses.${status}`)), submission.createdAt() && m("span", {
      className: "SubmissionList-meta"
    }, humanTime(submission.createdAt()))), status === 'rejected' && submission.reviewReason() && m("div", {
      className: "SubmissionList-reason"
    }, submission.reviewReason()), m("div", {
      className: "SubmissionList-actions"
    }, m(Button, {
      className: "Button Button--text",
      icon: "fas fa-pencil-alt",
      onclick: () => app.modal.show(SubmissionModal, {
        submission,
        onsaved: () => this.load()
      })
    }, trans('edit')), m(Button, {
      className: "Button Button--text",
      icon: "fas fa-times",
      onclick: () => this.remove(submission)
    }, trans('delete'))), status === 'approved' && m("div", {
      className: "SubmissionList-note helpText"
    }, trans('approved_note')));
  }
  remove(submission) {
    if (!confirm(String(trans('confirm_delete')))) return;
    submission.delete().then(() => this.load());
  }
}
flarum.reg.add('datlechin-placements', 'forum/components/SubmissionsUserPage', SubmissionsUserPage);